    private Map<String,Object> graph(Connection db,String actor,Map<String,Object>d)throws Exception {
        ContentInput.keys(d,"cursor","limit","query","type","organization","from","to");
        String cursor=ContentInput.text(d,"cursor",80,false),pending="",edgeAfter="";
        if(cursor.startsWith("E:")){
            String[]parts=cursor.split(":",-1);
            if(parts.length!=3||!uuid(parts[1])||!parts[2].isEmpty()&&!uuid(parts[2]))throw ContentInput.bad();
            pending=parts[1];edgeAfter=parts[2];
        }
        int limit=(int)ContentInput.number(d,"limit",40,1,100);
        Map<String,Object>request=new LinkedHashMap<>(d);if(!pending.isEmpty())request.put("cursor",pending);
        Map<String,Object>page=list(db,actor,"LIBRARY",request);
        @SuppressWarnings("unchecked") List<Map<String,Object>>future=(List<Map<String,Object>>)page.get("items");
        List<Map<String,Object>>candidates=new ArrayList<>();
        if(!pending.isEmpty()){Map<String,Object>m=visible(db,actor,pending,"LIBRARY");if(!graphMatches(m,d))throw missing();candidates.add(metadata(db,m));}
        candidates.addAll(future);
        List<Map<String,Object>>nodes=new ArrayList<>(),edges=new ArrayList<>();Map<String,Boolean>readable=new HashMap<>();ContentResponseBudget budget=new ContentResponseBudget();String completed=pending.isEmpty()?cursor:pending;
        for(Map<String,Object>node:candidates){
            String id=(String)node.get("id");
            if(nodes.size()==limit||!budget.take(node))return graphPage(nodes,edges,completed);
            nodes.add(node);readable.put(id,true);
            // Emit an edge when its larger endpoint is reached, including edges to prior pages.
            // Edge continuation is carried by the same opaque cursor the UI already preserves.
            String after=id.equals(pending)?edgeAfter:"",included=after;
            String sql="SELECT * FROM content_edge WHERE state='APPROVED' AND id>? AND ((from_id=? AND to_id<?) OR (to_id=? AND from_id<?)) ORDER BY id";
            try(PreparedStatement p=db.prepareStatement(sql)){
                p.setString(1,after);p.setString(2,id);p.setString(3,id);p.setString(4,id);p.setString(5,id);
                try(ResultSet r=p.executeQuery()){while(r.next()){
                    String other=id.equals(r.getString("from_id"))?r.getString("to_id"):r.getString("from_id");Boolean allowed=readable.get(other);
                    if(allowed==null){Map<String,Object>m=load(db,other);allowed=m.get("kind").equals("LIBRARY")&&readable(db,actor,m)&&graphMatches(m,d);readable.put(other,allowed);}
                    if(!allowed)continue;
                    Map<String,Object>edge=Map.of("id",r.getString("id"),"from",r.getString("from_id"),"to",r.getString("to_id"),"explanation",r.getString("explanation"),"state",r.getString("state"),"ai",r.getInt("ai")!=0);
                    if(!budget.take(edge))return graphPage(nodes,edges,"E:"+id+":"+included);
                    edges.add(edge);included=(String)edge.get("id");
                }}
            }
            completed=id;
        }
        return graphPage(nodes,edges,(String)page.get("nextCursor"));
    }
    private static boolean uuid(String value){try{return UUID.fromString(value).toString().equals(value);}catch(IllegalArgumentException invalid){return false;}}
    private static Map<String,Object> graphPage(List<Map<String,Object>>nodes,List<Map<String,Object>>edges,String cursor){return Map.of("nodes",nodes,"edges",edges,"nextCursor",cursor);}
    private boolean graphMatches(Map<String,Object>m,Map<String,Object>d)throws Exception {
        String query=ContentInput.text(d,"query",160,false).toLowerCase(Locale.ROOT),type=ContentInput.text(d,"type",20,false),org=ContentInput.text(d,"organization",80,false);
        long from=ContentInput.number(d,"from",0,0,Long.MAX_VALUE),to=ContentInput.number(d,"to",Long.MAX_VALUE,0,Long.MAX_VALUE);
        return(type.isEmpty()||type.equals(m.get("type")))&&(org.isEmpty()||org.equals(m.get("organization")))&&(query.isEmpty()||(m.get("title")+" "+m.get("body")).toLowerCase(Locale.ROOT).contains(query))&&(long)m.get("updatedAt")>=from&&(long)m.get("updatedAt")<=to;
    }
    private Map<String,Object> links(Connection db,String actor,Map<String,Object>d)throws Exception {
        ContentInput.keys(d,"id","state","limit");String material=ContentInput.id(d,"id"),state=ContentInput.text(d,"state",20,false);visible(db,actor,material,"LIBRARY");
        if(!Set.of("","PROPOSED","APPROVED","REJECTED").contains(state))throw ContentInput.bad();int limit=(int)ContentInput.number(d,"limit",100,1,100);List<Map<String,Object>>out=new ArrayList<>();
        try(PreparedStatement p=db.prepareStatement("SELECT * FROM content_edge WHERE (from_id=? OR to_id=?) AND (?='' OR state=?) ORDER BY id LIMIT 1000")){p.setString(1,material);p.setString(2,material);p.setString(3,state);p.setString(4,state);try(ResultSet r=p.executeQuery()){while(r.next()&&out.size()<limit){Map<String,Object>a=load(db,r.getString("from_id")),b=load(db,r.getString("to_id"));if(!readable(db,actor,a)||!readable(db,actor,b))continue;out.add(Map.of("id",r.getString("id"),"from",r.getString("from_id"),"to",r.getString("to_id"),"explanation",r.getString("explanation"),"state",r.getString("state"),"ai",r.getInt("ai")!=0));}}}
        return Map.of("items",out);
    }
    private Map<String,Object> propose(Connection db,String actor,Map<String,Object>d,boolean ai)throws Exception {ContentInput.keys(d,"from","to","explanation");String from=ContentInput.id(d,"from"),to=ContentInput.id(d,"to");if(from.equals(to))throw ContentInput.bad();Map<String,Object>a=visible(db,actor,from,"LIBRARY");visible(db,actor,to,"LIBRARY");access.require(actor,"LIBRARY_LINK",authScope(a));String explanation=ContentInput.text(d,"explanation",1000,true);if(from.compareTo(to)>0){String tmp=from;from=to;to=tmp;}if(exists(db,"SELECT 1 FROM content_edge WHERE from_id=? AND to_id=?",from,to))throw new CommunityException("CONFLICT","Связь уже предложена");String id=ContentInput.newId();exec(db,"INSERT INTO content_edge VALUES(?,?,?,?,?,?,?)",id,from,to,explanation,"PROPOSED",actor,ai?1:0);return Map.of("id",id,"from",from,"to",to,"explanation",explanation,"state","PROPOSED","ai",ai);}
