    private Map<String,Object> upload(Connection db,String actor,Map<String,Object>d)throws Exception {ContentInput.keys(d,"materialId","name","mime","base64");String id=ContentInput.id(d,"materialId");Map<String,Object>m=visible(db,actor,id,null);access.require(actor,perm((String)m.get("kind"),"EDIT"),authScope(m));if(!m.get("state").equals("DRAFT"))throw new CommunityException("CONFLICT","Сначала сохраните черновик материала");String name=ContentInput.text(d,"name",180,true),mime=ContentInput.text(d,"mime",80,true),base64=ContentInput.text(d,"base64",6_000_000,true);if(name.contains("/")||name.contains("\\")||name.equals(".")||name.equals(".."))throw ContentInput.bad();byte[]bytes;try{bytes=Base64.getDecoder().decode(base64);}catch(IllegalArgumentException e){throw ContentInput.bad();}if(bytes.length==0||bytes.length>MAX_FILE||!validMime(mime,bytes))throw ContentInput.bad();try(PreparedStatement p=db.prepareStatement("SELECT count(*),coalesce(sum(length(bytes)),0) FROM content_file WHERE material=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){r.next();if(r.getLong(1)>=32||r.getLong(2)+bytes.length>32L*1024*1024)throw new CommunityException("LIMIT","Достигнут лимит вложений материала");}}String file=ContentInput.newId(),hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));exec(db,"INSERT INTO content_file VALUES(?,?,?,?,?,?)",file,id,name,mime,hash,bytes);Arrays.fill(bytes,(byte)0);return Map.of("id",file,"materialId",id,"name",name,"mime",mime,"sha256",hash);}
    static boolean validMime(String mime,byte[]b){return switch(mime){case "image/png"->b.length>=24&&Arrays.equals(Arrays.copyOf(b,8),new byte[]{(byte)137,80,78,71,13,10,26,10})&&imageBounds(b,16);case "image/jpeg"->jpegBounds(b);case "image/webp"->webpBounds(b);case "application/pdf"->b.length>=8&&ascii(b,0,"%PDF-");case "video/mp4"->b.length>=12&&ascii(b,4,"ftyp");case "text/plain","text/markdown"->{try{String s=StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(b)).toString();yield s.indexOf('\0')<0;}catch(java.nio.charset.CharacterCodingException e){yield false;}}default->false;};}
    private static boolean boundedPixels(long w,long h){return w>0&&h>0&&w<=16384&&h<=16384&&w*h<=32_000_000;}
    private static boolean jpegBounds(byte[]b){
        if(b.length<12||(b[0]&255)!=255||(b[1]&255)!=216||(b[b.length-2]&255)!=255||(b[b.length-1]&255)!=217)return false;
        int p=2;while(p+4<=b.length){if((b[p++]&255)!=255)return false;while(p<b.length&&(b[p]&255)==255)p++;if(p>=b.length)return false;int marker=b[p++]&255;if(marker==0xD9||marker==0xDA)return false;if(marker==0x01||marker>=0xD0&&marker<=0xD7)continue;if(p+2>b.length)return false;int n=(b[p]&255)*256+(b[p+1]&255);if(n<2||p+n>b.length)return false;if(Set.of(0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF).contains(marker)){if(n<8)return false;return boundedPixels((b[p+5]&255)*256L+(b[p+6]&255),(b[p+3]&255)*256L+(b[p+4]&255));}p+=n;}return false;
    }
    private static int le24(byte[]b,int p){return (b[p]&255)|((b[p+1]&255)<<8)|((b[p+2]&255)<<16);}
    private static boolean webpBounds(byte[]b){
        if(b.length<30||!ascii(b,0,"RIFF")||!ascii(b,8,"WEBP"))return false;
        if(ascii(b,12,"VP8X"))return boundedPixels(1L+le24(b,24),1L+le24(b,27));
        if(ascii(b,12,"VP8L")&&(b[20]&255)==0x2f){long bits=Integer.toUnsignedLong((b[21]&255)|((b[22]&255)<<8)|((b[23]&255)<<16)|((b[24]&255)<<24));return boundedPixels((bits&0x3fff)+1,((bits>>>14)&0x3fff)+1);}
        return ascii(b,12,"VP8 ")&&(b[23]&255)==0x9d&&(b[24]&255)==0x01&&(b[25]&255)==0x2a&&boundedPixels(((b[26]&255)|((b[27]&255)<<8))&0x3fff,((b[28]&255)|((b[29]&255)<<8))&0x3fff);
    }
    private static boolean ascii(byte[]b,int offset,String s){if(b.length<offset+s.length())return false;for(int i=0;i<s.length();i++)if(b[offset+i]!=(byte)s.charAt(i))return false;return true;}
    private static boolean imageBounds(byte[]b,int o){long w=0,h=0;for(int i=0;i<4;i++){w=w*256+(b[o+i]&255);h=h*256+(b[o+4+i]&255);}return w>0&&h>0&&w<=16384&&h<=16384&&w*h<=32_000_000;}
    private Map<String,Object> download(Connection db,String actor,Map<String,Object>d)throws Exception {ContentInput.keys(d,"id");String id=ContentInput.id(d,"id");try(PreparedStatement p=db.prepareStatement("SELECT * FROM content_file WHERE id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw missing();visible(db,actor,r.getString("material"),null);return Map.of("id",id,"name",r.getString("name"),"mime",r.getString("mime"),"sha256",r.getString("sha256"),"base64",Base64.getEncoder().encodeToString(r.getBytes("bytes")),"disposition","attachment");}}}
