    private Map<String,Object> notifications(Connection db,String actor,Map<String,Object>d)throws Exception {ContentInput.keys(d,"limit","cursor");int limit=(int)ContentInput.number(d,"limit",50,1,100);String cursor=ContentInput.text(d,"cursor",80,false);List<Map<String,Object>>out=new ArrayList<>();try(PreparedStatement p=db.prepareStatement("SELECT * FROM content_notification WHERE actor=? AND id>? ORDER BY id LIMIT 512")){p.setString(1,actor);p.setString(2,cursor);try(ResultSet r=p.executeQuery()){while(r.next()&&out.size()<limit){Map<String,Object>m=load(db,r.getString("material"));if(!readable(db,actor,m))continue;out.add(Map.of("id",r.getString("id"),"materialId",m.get("id"),"title",m.get("title"),"category",r.getString("category"),"createdAt",r.getLong("created"),"read",r.getInt("seen")!=0));}}}try(PreparedStatement p=db.prepareStatement("SELECT * FROM content_account_notification WHERE actor=? AND id>? ORDER BY id LIMIT 512")){p.setString(1,actor);p.setString(2,cursor);try(ResultSet r=p.executeQuery()){while(r.next())out.add(Map.of("id",r.getString("id"),"materialId","","title",r.getString("title"),"category",r.getString("category"),"createdAt",r.getLong("created"),"read",r.getInt("seen")!=0));}}out.sort(Comparator.comparing(x->(String)x.get("id")));boolean more=out.size()>limit;if(more)out=new ArrayList<>(out.subList(0,limit));return Map.of("items",out,"nextCursor",more?out.get(out.size()-1).get("id"):"");}
